SELECT "nct", "author", "year", "pubmed_id", "trial_phase", "treatment_regimen", "name_of_ici", "class_of_ici", "type_of_combination", "control_regimen", "type_of_control", "cancer_type" FROM public."clinical_trials" WHERE "cancer_type" = 'Breast' AND "trial_phase" = 'Phase 2' AND "class_of_ici" = 'PD1' AND "monotherapy_combination" = 'Yes' AND "type_of_combination" = 'Monotherapy' AND "is_pd_l1_positivity_inclusion_criteria" = 'Yes';